import requests
import json
import pandas as pd
import seaborn as sns
HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    try:
        response = requests.get(url, params=parameters, headers=HEADERS)
        response.raise_for_status()
        data = json.loads(response.text)

        if not isinstance(data, dict) or not data:
            raise Exception("Invalid or empty data received.")

        df = pd.DataFrame(data)
        if df.empty or not any(df.dtypes.apply(lambda x: pd.api.types.is_numeric_dtype(x))):
            raise Exception("No numerical data available for correlation.")

        correlation_matrix = df.corr()
        ax = sns.heatmap(correlation_matrix, annot=True, cmap="coolwarm")
        return df, ax
    except Exception as e:
        raise Exception(f"An error occurred: {e}")

