import json
SUCCESS_RESPONSE = {
    'status': 'success',
    'message': 'Data received successfully.'
}
def task_func():
    class HTTPPostHandler(http.server.BaseHTTPRequestHandler):
        def do_POST(self):
            content_type = self.headers.get('Content-Type')
            if content_type != 'application/json':
                self.send_response(400)
                self.send_header('Content-Type', 'application/json')
                self.end_headers()
                response = {'status': 'error', 'message': 'Content-Type header is not application/json'}
                self.wfile.write(json.dumps(response).encode('utf-8'))
                return

            try:
                content_length = int(self.headers.get('Content-Length'))
                body = self.rfile.read(content_length)
                data = json.loads(body)
                if 'data' not in data:
                    self.send_response(400)
                    self.send_header('Content-Type', 'application/json')
                    self.end_headers()
                    response = {'status': 'error', 'message': 'No data key in request'}
                    self.wfile.write(json.dumps(response).encode('utf-8'))
                else:
                    self.send_response(200)
                    self.send_header('Content-Type', 'application/json')
                    self.end_headers()
                    response = SUCCESS_RESPONSE
                    self.wfile.write(json.dumps(response).encode('utf-8'))
            except json.JSONDecodeError:
                self.send_response(400)
                self.send_header('Content-Type', 'application/json')
                self.end_headers()
                response = {'status': 'error', 'message': 'Invalid JSON'}
                self.wfile.write(json.dumps(response).encode('utf-8'))
    return HTTPPostHandler

