                processed_data[key] = process_value(value)

    flat_values = []

    def flatten(data):
        if isinstance(data, dict):
            for v in data.values():
                flatten(v)
        elif isinstance(data, list):
            for v in data:
                flatten(v)
        else:
            flat_values.append(data)

    flatten(processed_data)
