import json
import re
from collections import Counter
REPLACE_NONE = "None"
def task_func(json_str):
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        return {"data": {}, "value_counts": Counter()}

    def replace_email(value):
        if isinstance(value, str) and re.match(r'^[^@]+@[^@]+\.[^@]+$', value):
            return REPLACE_NONE
        return value

    def process_dict(d):
        return {k: replace_email(v) for k, v in d.items() if v is not None}

    if isinstance(data, dict):
        processed_data = process_dict(data)
    elif isinstance(data, list):
        processed_data = [process_dict(item) for item in data if isinstance(item, dict)]
    else:
        processed_data = {}

    flattened_values = []
    if isinstance(processed_data, dict):
        flattened_values.extend(processed_data.values())
    elif isinstance(processed_data, list):
        for item in processed_data:
            flattened_values.extend(item.values())

    value_counts = Counter(flattened_values)
    return {"data": processed_data, "value_counts": value_counts}

