import json
import os
import math
def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    try:
        data = json.loads(json_data)
        if not data or not all(isinstance(item.get('Country'), str) and isinstance(item.get('Population'), (int, float)) and item.get('Population') >= 0 for item in data):
            raise ValueError("Invalid JSON data")
    except json.JSONDecodeError:
        raise ValueError("Malformed JSON data")

    for item in data:
        item['Population'] = math.floor(item['Population'])

    df = pd.DataFrame(data)
    if not os.access(output_dir, os.W_OK):
        raise IOError("Cannot write to the specified directory")

    output_path = os.path.join(output_dir, file_name)
    df.to_csv(output_path, index=False)
    return output_path, df

