import json
import os
import math
def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    try:
        data = json.loads(json_data)
        if not isinstance(data, list) or not data:
            raise ValueError
        records = []
        for entry in data:
            if not isinstance(entry, dict) or "Country" not in entry or "Population" not in entry:
                raise ValueError
            country = entry["Country"]
            population = entry["Population"]
            if not isinstance(country, str) or not isinstance(population, (int, float)) or population < 0:
                raise ValueError
            records.append({"Country": country, "Population": math.floor(population)})
        df = pd.DataFrame(records, columns=["Country", "Population"])
        output_path = os.path.join(output_dir, file_name)
        df.to_csv(output_path, index=False)
        return output_path, df
    except ValueError:
        raise ValueError
    except OSError:
        raise IOError

